using System.Collections.Immutable;
using System.Reflection;
using System.Reflection.Metadata;
using System.Text.Json;
namespace MetadataDiagnostics;
public static class ApiAudit
{
 public static object Run(JsonElement profile)
 {
  var images=new List<MetadataImage>();var refs=new List<object>();var patches=new List<object>();var budget=new OutputBudget();var gaps=new BoundedTextList(budget);var findings=new BoundedTextList(budget);int typeCount=0,memberCount=0,fixedCount=0,bindings=0,dynamicCount=0,manualCount=0,transpilers=0;
  try {
   var subjects=profile.GetProperty("Assemblies").EnumerateArray().Select(x=>MetadataImage.ValidatePath(x.GetString()!)).ToArray();
   var paths=subjects.Concat(profile.GetProperty("Dependencies").EnumerateArray().Select(x=>MetadataImage.ValidatePath(x.GetString()!))).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
   if(paths.Length>256||subjects.Length==0)throw new InvalidDataException("1..256 explicit assemblies required.");
   long total=0;foreach(var path in paths){total+=new FileInfo(path).Length;if(total>512L*1024*1024)throw new InvalidDataException("Aggregate input bound exceeded.");images.Add(new MetadataImage(path));}
   var duplicate=images.GroupBy(x=>x.AssemblyName,StringComparer.OrdinalIgnoreCase).Where(x=>x.Count()>1).ToArray();
   if(duplicate.Length>0)throw new InvalidDataException("Duplicate assembly simple names refused: "+string.Join(",",duplicate.Select(x=>x.Key)));
   var map=images.ToDictionary(x=>x.AssemblyName,StringComparer.Ordinal);var scope=profile.GetProperty("ReferenceAssemblyNames").EnumerateArray().Select(x=>x.GetString()!).ToHashSet(StringComparer.Ordinal);
   if(scope.Count==0||scope.Any(string.IsNullOrWhiteSpace))throw new InvalidDataException("Explicit nonempty reference scope required.");
   foreach(var image in images.Where(x=>subjects.Contains(x.Path,StringComparer.OrdinalIgnoreCase))) {
    if(image.Reader.TypeDefinitions.Count>100000||image.Reader.MemberReferences.Count>500000)throw new InvalidDataException("Metadata row limit exceeded.");
    foreach(var h in image.Reader.TypeReferences){var t=image.Reader.GetTypeReference(h);var assembly=Scope(image,t.ResolutionScope);if(assembly==null){gaps.Add(image.AssemblyName+": unsupported type reference scope");continue;}if(!scope.Contains(assembly))continue;typeCount++;var status=ResolveType(image,h,map,out var owner,out var type,out var detail);AddRow(refs,new{Assembly=image.AssemblyName,Kind="Type",Identity=image.TypeName(h),Status=status,Detail=detail});Classify(status,detail);}
    foreach(var h in image.Reader.MemberReferences){var member=image.Reader.GetMemberReference(h);var parent=member.Parent;if(parent.Kind!=HandleKind.TypeReference){if(parent.Kind==HandleKind.TypeSpecification){var ownerScope=GenericOwnerScope(image,(TypeSpecificationHandle)parent);if(ownerScope==null)gaps.Add(image.AssemblyName+": unsupported member owner scope requires review: "+image.EntityName(h));else if(scope.Contains(ownerScope))gaps.Add(image.AssemblyName+": generic member owner requires review: "+image.EntityName(h));}continue;}
     var tr=image.Reader.GetTypeReference((TypeReferenceHandle)parent);var assembly=Scope(image,tr.ResolutionScope);if(assembly==null||!scope.Contains(assembly))continue;memberCount++;
     var status=ResolveType(image,(TypeReferenceHandle)parent,map,out var target,out var type,out var detail);var identity=image.EntityName(h);
     if(status=="Resolved"){
      var definition=target!.Reader.GetTypeDefinition(type);var candidates=member.GetKind()==MemberReferenceKind.Method?definition.GetMethods().Select(target.MethodSignature).ToArray():definition.GetFields().Select(target.FieldSignature).ToArray();
      if(candidates.Contains(identity,StringComparer.Ordinal))status="Resolved";
      else if(!definition.BaseType.IsNil){status="UnsupportedInheritance";detail="No exact declared member; inherited resolution requires review: "+identity;}
      else {status="MissingMember";detail="Exact compiled signature not found: "+identity;}
     }
     AddRow(refs,new{Assembly=image.AssemblyName,Kind=member.GetKind().ToString(),Identity=identity,Status=status,Detail=detail});Classify(status,detail);
    }
    foreach(var th in image.Reader.TypeDefinitions){var type=image.Reader.GetTypeDefinition(th);var methods=type.GetMethods().ToArray();var classAttrs=PatchAttributes(image,type.GetCustomAttributes());var methodAttrs=methods.Select(m=>(Handle:m,Attrs:PatchAttributes(image,image.Reader.GetMethodDefinition(m).GetCustomAttributes()))).Where(x=>x.Attrs.Count>0).ToArray();
     var isPatch=classAttrs.Count>0||methodAttrs.Length>0;
     foreach(var ah in type.GetCustomAttributes().Concat(methods.SelectMany(m=>image.Reader.GetMethodDefinition(m).GetCustomAttributes()))){var an=AttributeName(image,ah);if(new[]{"HarmonyPriority","HarmonyBefore","HarmonyAfter","HarmonyPrepare","HarmonyCleanup","HarmonyReversePatch"}.Any(n=>an.EndsWith("]HarmonyLib."+n,StringComparison.Ordinal)))gaps.Add("Harmony lifecycle/order attribute requires review: "+an+" on "+image.TypeName(th));}
     if(image.TypeName(th).EndsWith("]HarmonyLib.Harmony",StringComparison.Ordinal)&&methods.Any(h=>image.Reader.GetString(image.Reader.GetMethodDefinition(h).Name)=="Patch")){manualCount++;gaps.Add("Harmony Patch API declared in subject; manual registration requires review: "+image.TypeName(th));}
     foreach(var mh in methods){var m=image.Reader.GetMethodDefinition(mh);var name=image.Reader.GetString(m.Name);if(name=="Transpiler"||HasAttribute(image,m.GetCustomAttributes(),"HarmonyTranspiler")){transpilers++;gaps.Add("Transpiler instructions not verified: "+image.MethodSignature(mh));}if(IsDynamic(image,m)){dynamicCount++;gaps.Add("Dynamic target provider not executed: "+image.MethodSignature(mh));}}
     if(!isPatch)continue;
     if(methods.Any(m=>IsDynamic(image,image.Reader.GetMethodDefinition(m))))continue;
     var groups=methodAttrs.Length>0?methodAttrs.Select(x=>(Attrs:classAttrs.Concat(x.Attrs).ToList(),Hook:(MethodDefinitionHandle?)x.Handle)):new[]{(Attrs:classAttrs,Hook:(MethodDefinitionHandle?)null)};
     foreach(var group in groups){fixedCount++;try{
      var spec=ReadTarget(image,group.Attrs);var target=FindTarget(spec,map);var status=target.Status;var detail=target.Detail;Classify(status,detail);
      if(status!="Resolved"){AddRow(patches,new{Patch=image.TypeName(th),Target=spec.Type+"::"+spec.Name,Status=status,TargetStatus=status,BindingStatus="NotRun",Detail=detail});continue;}
      var hooks=group.Hook.HasValue?new[]{group.Hook.Value}:methods.Where(m=>{var md=image.Reader.GetMethodDefinition(m);return image.Reader.GetString(md.Name) is "Prefix" or "Postfix" or "Finalizer"||HasAttribute(image,md.GetCustomAttributes(),"HarmonyPrefix")||HasAttribute(image,md.GetCustomAttributes(),"HarmonyPostfix")||HasAttribute(image,md.GetCustomAttributes(),"HarmonyFinalizer");}).ToArray();
      var findingsBefore=findings.Count;var gapsBefore=gaps.Count;
      if(hooks.Length==0)gaps.Add("No recognized Prefix/Postfix/Finalizer binding hooks: "+image.TypeName(th));
      foreach(var hook in hooks){bindings++;CheckBinding(image,hook,target.Image!,target.Method,findings,gaps);}
      var bindingStatus=hooks.Length==0?"NotRun":findings.Count>findingsBefore?"Failed":gaps.Count>gapsBefore?"RequiresReview":"CheckedSupportedBindings";
      AddRow(patches,new{Patch=image.TypeName(th),Target=spec.Type+"::"+spec.Name,Status=status,TargetStatus=status,BindingStatus=bindingStatus,Detail=detail});
     }catch(Exception e)when(e is NotSupportedException or BadImageFormatException or InvalidDataException){gaps.Add("Unsupported Harmony attributes on "+image.TypeName(th)+": "+e.Message);}}
    }
    foreach(var mh in image.Reader.MemberReferences){var m=image.Reader.GetMemberReference(mh);if(image.Reader.GetString(m.Name)=="Patch"&&m.Parent.Kind==HandleKind.TypeReference&&image.TypeName(m.Parent).EndsWith("]HarmonyLib.Harmony",StringComparison.Ordinal)){manualCount++;gaps.Add("Manual Harmony registration reference requires review: "+image.EntityName(mh));}}
   }
   var inputs=images.Select(x=>new{Path=x.Path,Status="Present",SHA256=x.Sha256,MVID=x.Mvid,AssemblyIdentity=x.FullIdentity}).ToArray();
   return new{State=findings.Count>0?"Failed":gaps.Count>0?"CheckedWithGaps":"CheckedSupportedScope",Inputs=inputs,References=refs,Patches=patches,Coverage=new{SubjectAssemblies=subjects.Length,ScopedTypes=typeCount,ScopedMembers=memberCount,FixedTargets=fixedCount,BindingChecks=bindings,DynamicProviders=dynamicCount,ManualRegistrationReferences=manualCount,Transpilers=transpilers},Gaps=gaps.Distinct().ToArray(),Findings=findings.Distinct().ToArray()};
   void AddRow(List<object> rows,object row){if(refs.Count+patches.Count>=20000)throw new InvalidDataException("Output row bound exceeded; narrow selected scope.");var text=JsonSerializer.Serialize(row);using(var doc=JsonDocument.Parse(text)){foreach(var property in doc.RootElement.EnumerateObject())if(property.Value.ValueKind==JsonValueKind.String&&property.Value.GetString()!.Length>8192)throw new InvalidDataException("Diagnostic identity exceeds 8192 characters.");}budget.Add(text);rows.Add(row);}
   void Classify(string status,string detail){if(status.StartsWith("Missing",StringComparison.Ordinal)||status=="AmbiguousTarget"||status=="IdentityMismatch")findings.Add(detail);else if(status!="Resolved")gaps.Add(detail);}
  }catch(Exception ex)when(ex is InvalidDataException or NotSupportedException or BadImageFormatException){return new{State="Failed",Inputs=images.Select(x=>new{Path=x.Path,Status="Present",SHA256=x.Sha256,MVID=x.Mvid,AssemblyIdentity=x.FullIdentity}).ToArray(),References=Array.Empty<object>(),Patches=Array.Empty<object>(),Coverage=new{},Gaps=new[]{ex.GetType().Name+": "+ex.Message},Findings=Array.Empty<object>()};}finally{foreach(var image in images)image.Dispose();}
 }
 static string? GenericOwnerScope(MetadataImage image,TypeSpecificationHandle handle){var blob=image.Reader.GetBlobReader(image.Reader.GetTypeSpecification(handle).Signature);if(blob.ReadByte()!=0x15)return null;var kind=blob.ReadByte();if(kind is not (0x11 or 0x12))return null;var prototype=blob.ReadTypeHandle();return prototype.Kind switch{HandleKind.TypeReference=>Scope(image,image.Reader.GetTypeReference((TypeReferenceHandle)prototype).ResolutionScope),HandleKind.TypeDefinition=>image.AssemblyName,_=>null};}
 static string? Scope(MetadataImage image,EntityHandle h){int depth=0;while(h.Kind==HandleKind.TypeReference){if(++depth>64)throw new NotSupportedException("Nested reference depth exceeded.");h=image.Reader.GetTypeReference((TypeReferenceHandle)h).ResolutionScope;}return h.Kind==HandleKind.AssemblyReference?image.Reader.GetString(image.Reader.GetAssemblyReference((AssemblyReferenceHandle)h).Name):h.Kind==HandleKind.ModuleDefinition?image.AssemblyName:null;}
 static string ResolveType(MetadataImage source,TypeReferenceHandle handle,Dictionary<string,MetadataImage> map,out MetadataImage? target,out TypeDefinitionHandle type,out string detail){target=null;type=default;var reference=source.Reader.GetTypeReference(handle);var root=reference.ResolutionScope;int depth=0;while(root.Kind==HandleKind.TypeReference){if(++depth>64)throw new NotSupportedException("Nested type depth exceeded.");root=source.Reader.GetTypeReference((TypeReferenceHandle)root).ResolutionScope;}
  var name=Scope(source,root);detail=source.TypeName(handle);if(name==null)return "UnsupportedScope";if(!map.TryGetValue(name,out target)){detail="Explicit dependency missing for "+name+": "+detail;return "MissingDependency";}
  if(root.Kind==HandleKind.AssemblyReference&&source.AssemblyReferenceIdentity((AssemblyReferenceHandle)root)!=target.FullIdentity){detail="Exact assembly identity mismatch for "+name;return "IdentityMismatch";}
  var wanted=source.TypeName(handle);var resolvedImage=target;var matches=resolvedImage.Reader.TypeDefinitions.Where(h=>resolvedImage.TypeName(h)==wanted).ToArray();if(matches.Length==1){type=matches[0];return "Resolved";}
  if(target.Reader.ExportedTypes.Count>0){detail="Type unavailable directly; forwarding/exported types require review: "+wanted;return "UnsupportedForwarding";}detail="Type not found: "+wanted;return "MissingType";
 }
 static bool IsDynamic(MetadataImage i,MethodDefinition m)=>i.Reader.GetString(m.Name) is "TargetMethod" or "TargetMethods"||HasAttribute(i,m.GetCustomAttributes(),"HarmonyTargetMethod")||HasAttribute(i,m.GetCustomAttributes(),"HarmonyTargetMethods");
 static string AttributeName(MetadataImage i,CustomAttributeHandle h){var c=i.Reader.GetCustomAttribute(h).Constructor;return c.Kind==HandleKind.MemberReference?i.TypeName(i.Reader.GetMemberReference((MemberReferenceHandle)c).Parent):c.Kind==HandleKind.MethodDefinition?i.TypeName(i.Reader.GetMethodDefinition((MethodDefinitionHandle)c).GetDeclaringType()):"";}
 static bool HasAttribute(MetadataImage i,CustomAttributeHandleCollection attrs,string name)=>attrs.Any(h=>AttributeName(i,h).EndsWith("]HarmonyLib."+name,StringComparison.Ordinal));
 static List<CustomAttributeHandle> PatchAttributes(MetadataImage i,CustomAttributeHandleCollection attrs)=>attrs.Where(h=>AttributeName(i,h).EndsWith("]HarmonyLib.HarmonyPatch",StringComparison.Ordinal)).ToList();
 sealed record TargetSpec(string Type,string? Assembly,string Name,string[]? Args);
 static TargetSpec ReadTarget(MetadataImage image,List<CustomAttributeHandle> attrs){string? type=null,assembly=null,name=null;string[]? args=null;int methodType=0;
  foreach(var ah in attrs){var value=image.Reader.GetCustomAttribute(ah).DecodeValue(new AttributeProvider());if(value.NamedArguments.Length>0)throw new NotSupportedException("Named Harmony arguments require review.");foreach(var arg in value.FixedArguments){if(arg.Type=="System.Type"){var text=(string?)arg.Value??throw new NotSupportedException("Null target type.");var parts=text.Split(',');if(parts[0].Contains('['))throw new NotSupportedException("Generic target types require review.");type=parts[0];assembly=parts.Length>1?new AssemblyName(text[(text.IndexOf(',')+1)..].Trim()).FullName:image.FullIdentity;if(string.IsNullOrEmpty(assembly))throw new NotSupportedException("Full target assembly identity required.");}else if(arg.Type=="String")name=(string?)arg.Value;else if(arg.Type=="System.Type[]"){args=((ImmutableArray<CustomAttributeTypedArgument<string>>)arg.Value!).Select(x=>NormalizeSerialized((string)x.Value!,image)).ToArray();}else if(arg.Type.EndsWith("MethodType",StringComparison.Ordinal))methodType=Convert.ToInt32(arg.Value);else throw new NotSupportedException("Harmony argument "+arg.Type);}}
  if(type==null)throw new NotSupportedException("Target type not statically specified.");name=methodType switch{0=>name,1=>"get_"+name,2=>"set_"+name,3=>".ctor",4=>".cctor",_=>throw new NotSupportedException("Unsupported method type.")};if(name==null)throw new NotSupportedException("Target method name absent.");return new(type,assembly,name,args);
 }
 static string NormalizeSerialized(string s,MetadataImage image){
  var comma=s.IndexOf(',');var name=comma<0?s:s[..comma];
  if(name.IndexOfAny(new[]{'[',']','&','*','!'})>=0)throw new NotSupportedException("Constructed/element selector identity requires review.");
  var identity=comma<0?image.FullIdentity:new AssemblyName(s[(comma+1)..].Trim()).FullName;
  if(identity==null)throw new NotSupportedException("Selector assembly identity unavailable.");
  if(TrustedPrimitive(name,identity))return "primitive:"+name;
  return identity+"|"+name;
 }
 static bool TrustedPrimitive(string name,string identity){
  if(!PrimitiveNames.Values.Contains(name,StringComparer.Ordinal))return false;
  var assembly=new AssemblyName(identity);var token=Convert.ToHexString(assembly.GetPublicKeyToken()??Array.Empty<byte>()).ToLowerInvariant();
  return (assembly.Name,token) is ("mscorlib","b77a5c561934e089") or ("System.Private.CoreLib","7cec85d7bea7798e") or ("System.Runtime","b03f5f7f11d50a3a");
 }
 static readonly Dictionary<string,string> PrimitiveNames=new(StringComparer.Ordinal){["SByte"]="System.SByte",["Byte"]="System.Byte",["Int16"]="System.Int16",["UInt16"]="System.UInt16",["UInt32"]="System.UInt32",["UInt64"]="System.UInt64",["Char"]="System.Char",["IntPtr"]="System.IntPtr",["UIntPtr"]="System.UIntPtr",["TypedReference"]="System.TypedReference",["Int32"]="System.Int32",["Boolean"]="System.Boolean",["String"]="System.String",["Object"]="System.Object",["Void"]="System.Void",["Int64"]="System.Int64",["Single"]="System.Single",["Double"]="System.Double"};
 static string CandidateArgument(MetadataImage image,string signature){
  if(PrimitiveNames.TryGetValue(signature,out var primitive))return "primitive:"+primitive;
  if(signature.StartsWith("class ",StringComparison.Ordinal))signature=signature[6..];else if(signature.StartsWith("valuetype ",StringComparison.Ordinal))signature=signature[10..];
  if(!signature.StartsWith('['))throw new NotSupportedException("Parameter selector signature identity requires review.");
  var close=signature.IndexOf(']');if(close<2)throw new NotSupportedException("Parameter assembly scope unavailable.");
  var assembly=signature[1..close];var name=signature[(close+1)..];
  if(name.IndexOfAny(new[]{'[',']','<','>','&','*','!'})>=0||name.Contains(" mod",StringComparison.Ordinal))throw new NotSupportedException("Constructed/element parameter identity requires review.");
  string identity;
  if(assembly==image.AssemblyName)identity=image.FullIdentity;
  else {var references=image.Reader.AssemblyReferences.Where(h=>image.Reader.GetString(image.Reader.GetAssemblyReference(h).Name)==assembly).ToArray();if(references.Length!=1)throw new NotSupportedException("Unique parameter AssemblyRef identity unavailable.");identity=image.AssemblyReferenceIdentity(references[0]);}
  return identity+"|"+name;
 }
 sealed record TargetResult(string Status,string Detail,MetadataImage? Image=null,MethodDefinitionHandle Method=default);
 static TargetResult FindTarget(TargetSpec spec,Dictionary<string,MetadataImage> map){var owners=map.Values.Where(i=>spec.Assembly!=null&&i.FullIdentity==spec.Assembly).SelectMany(i=>i.Reader.TypeDefinitions.Where(h=>i.TypeName(h)=="["+i.AssemblyName+"]"+spec.Type).Select(h=>(Image:i,Handle:h))).ToArray();if(owners.Length!=1)return new(owners.Length==0?"MissingTargetType":"AmbiguousTarget","Target type matches="+owners.Length+": "+spec.Type);var owner=owners[0];var type=owner.Image.Reader.GetTypeDefinition(owner.Handle);if(type.GetGenericParameters().Count>0)return new("UnsupportedGenericTarget","Generic Harmony target requires review.");
  var candidates=type.GetMethods().Where(h=>owner.Image.Reader.GetString(owner.Image.Reader.GetMethodDefinition(h).Name)==spec.Name).ToArray();if(spec.Args!=null)candidates=candidates.Where(h=>owner.Image.Reader.GetMethodDefinition(h).DecodeSignature(owner.Image.Provider,(object?)null).ParameterTypes.Select(p=>CandidateArgument(owner.Image,p)).SequenceEqual(spec.Args)).ToArray();
  if(candidates.Length!=1)return new(candidates.Length==0?"MissingTarget":"AmbiguousTarget","Target method matches="+candidates.Length+": "+spec.Type+"::"+spec.Name);if(owner.Image.Reader.GetMethodDefinition(candidates[0]).GetGenericParameters().Count>0)return new("UnsupportedGenericTarget","Generic target method requires review.");return new("Resolved",owner.Image.MethodSignature(candidates[0]),owner.Image,candidates[0]);
 }
 static void CheckBinding(MetadataImage patch,MethodDefinitionHandle hook,MetadataImage target,MethodDefinitionHandle original,BoundedTextList findings,BoundedTextList gaps){var p=patch.Reader.GetMethodDefinition(hook);var o=target.Reader.GetMethodDefinition(original);if(HasAttribute(patch,p.GetCustomAttributes(),"HarmonyArgument")||p.GetParameters().Any(h=>HasAttribute(patch,patch.Reader.GetParameter(h).GetCustomAttributes(),"HarmonyArgument"))){gaps.Add("HarmonyArgument mapping requires review: "+patch.MethodSignature(hook));return;}if((p.Attributes&MethodAttributes.Static)==0)findings.Add("Harmony hook must be static: "+patch.MethodSignature(hook));if(p.GetGenericParameters().Count>0)gaps.Add("Generic Harmony hook requires review: "+patch.MethodSignature(hook));var ps=p.DecodeSignature(patch.Provider,(object?)null);var role=patch.Reader.GetString(p.Name);if(HasAttribute(patch,p.GetCustomAttributes(),"HarmonyPrefix"))role="Prefix";else if(HasAttribute(patch,p.GetCustomAttributes(),"HarmonyPostfix"))role="Postfix";else if(HasAttribute(patch,p.GetCustomAttributes(),"HarmonyFinalizer"))role="Finalizer";if(role=="Prefix"&&ps.ReturnType!="Void"&&ps.ReturnType!="Boolean")findings.Add("Invalid Prefix return type: "+patch.MethodSignature(hook));else if(role=="Postfix"&&ps.ReturnType!="Void")gaps.Add("Postfix return/pass-through contract requires review: "+patch.MethodSignature(hook));else if(role=="Finalizer"&&ps.ReturnType!="Void")gaps.Add("Finalizer exception return contract requires review: "+patch.MethodSignature(hook));else if(role is not ("Prefix" or "Postfix" or "Finalizer")){gaps.Add("Unknown method-level patch hook role: "+patch.MethodSignature(hook));return;}if(!CompleteParameters(patch,p,ps.ParameterTypes.Length)||!CompleteParameters(target,o,o.DecodeSignature(target.Provider,(object?)null).ParameterTypes.Length)){gaps.Add("Incomplete/ambiguous parameter metadata requires review: "+patch.MethodSignature(hook));return;}var os=o.DecodeSignature(target.Provider,(object?)null);var originalNames=o.GetParameters().Select(h=>target.Reader.GetParameter(h)).Where(x=>x.SequenceNumber>0).ToDictionary(x=>target.Reader.GetString(x.Name),x=>(int)x.SequenceNumber-1,StringComparer.Ordinal);
  foreach(var ph in p.GetParameters()){var parameter=patch.Reader.GetParameter(ph);if(parameter.SequenceNumber==0)continue;var name=patch.Reader.GetString(parameter.Name);var actual=ps.ParameterTypes[parameter.SequenceNumber-1];string? expected=null;
   if(name=="__instance"){if((o.Attributes&MethodAttributes.Static)!=0){findings.Add("__instance used for static target: "+patch.MethodSignature(hook));continue;}expected="class "+target.TypeName(o.GetDeclaringType());if(actual!=expected&&actual!=expected+"&")gaps.Add("__instance assignability requires review: "+patch.MethodSignature(hook));continue;}
   if(name=="__result"){if(os.ReturnType=="Void"){findings.Add("__result used for void target: "+patch.MethodSignature(hook));continue;}expected=os.ReturnType;}
   else if(name.StartsWith("___",StringComparison.Ordinal)){var fields=target.Reader.GetTypeDefinition(o.GetDeclaringType()).GetFields().Where(h=>target.Reader.GetString(target.Reader.GetFieldDefinition(h).Name)==name[3..]).ToArray();if(fields.Length!=1){gaps.Add("Injected field unavailable directly; inherited field review required: "+name);continue;}expected=target.Reader.GetFieldDefinition(fields[0]).DecodeSignature(target.Provider,(object?)null);}
   else if(name.StartsWith("__",StringComparison.Ordinal)){gaps.Add("Special Harmony binding requires review: "+name);continue;}
   else if(originalNames.TryGetValue(name,out var index))expected=os.ParameterTypes[index];else{findings.Add("Unknown original parameter binding "+name+": "+patch.MethodSignature(hook));continue;}
   if(actual!=expected&&actual!=expected+"&"){var detail="Binding type mismatch "+name+": "+actual+" versus "+expected+" in "+patch.MethodSignature(hook);if(actual.Contains("class ",StringComparison.Ordinal)||expected.Contains("class ",StringComparison.Ordinal))gaps.Add("Assignability requires review: "+detail);else findings.Add(detail);}
  }
 }
 static bool CompleteParameters(MetadataImage i,MethodDefinition method,int count){var rows=method.GetParameters().Select(h=>i.Reader.GetParameter(h)).Where(p=>p.SequenceNumber!=0).ToArray();return rows.Length==count&&rows.Select(p=>(int)p.SequenceNumber).Order().SequenceEqual(Enumerable.Range(1,count))&&rows.All(p=>!string.IsNullOrEmpty(i.Reader.GetString(p.Name)))&&rows.Select(p=>i.Reader.GetString(p.Name)).Distinct(StringComparer.Ordinal).Count()==count;}
 sealed class OutputBudget {int chars;public void Add(string text){if(text.Length>65536)throw new InvalidDataException("Diagnostic row/text exceeds bounded size.");chars+=text.Length;if(chars>4*1024*1024)throw new InvalidDataException("Diagnostic output budget exceeded; narrow scope.");}}
 sealed class BoundedTextList(OutputBudget budget):List<string>{public new void Add(string text){if(Count>=9999||text.Length>8192)throw new InvalidDataException("Diagnostic text/count bound exceeded.");budget.Add(text);base.Add(text);}}
 sealed class AttributeProvider : ICustomAttributeTypeProvider<string>{public string GetPrimitiveType(PrimitiveTypeCode c)=>c.ToString();public string GetSystemType()=>"System.Type";public bool IsSystemType(string t)=>t=="System.Type";public string GetSZArrayType(string e)=>e+"[]";public string GetTypeFromDefinition(MetadataReader r,TypeDefinitionHandle h,byte k){var t=r.GetTypeDefinition(h);return r.GetString(t.Namespace)+"."+r.GetString(t.Name);}public string GetTypeFromReference(MetadataReader r,TypeReferenceHandle h,byte k){var t=r.GetTypeReference(h);return r.GetString(t.Namespace)+"."+r.GetString(t.Name);}public string GetTypeFromSerializedName(string n)=>n;public PrimitiveTypeCode GetUnderlyingEnumType(string t)=>t=="HarmonyLib.MethodType"?PrimitiveTypeCode.Int32:throw new NotSupportedException("Unknown attribute enum.");}
}
